package com.feimao.mapper;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import org.apache.ibatis.annotations.Delete;
import org.apache.ibatis.annotations.Mapper;
import org.apache.ibatis.annotations.Param;
import org.apache.ibatis.annotations.Select;
import org.apache.ibatis.annotations.Update;
import org.apache.ibatis.annotations.Insert;

@Mapper
public interface BusinessAdminMapper {
  @Select("select id,username,nickname,avatar,password,salt,status from ymcx_admin where username=#{username}")
  Map<String,Object> loginAdmin(@Param("username") String username);
  @Update("update ymcx_admin set loginfailure=loginfailure+1 where id=#{id}") int loginFailed(@Param("id") long id);
  @Update("update ymcx_admin set loginfailure=0,logintime=#{now},updatetime=#{now},token=#{token} where id=#{id}") int loginSucceeded(@Param("id") long id,@Param("token") String token,@Param("now") long now);

  @Select("select (select count(*) from ymcx_user where status='normal') users,(select count(*) from ymcx_order where is_delete=1) orders,(select count(*) from ymcx_merchant where is_delete=1 and deletetime is null and examine_status=1) pending_merchants,(select count(*) from ymcx_shop where is_delete=1 and deletetime is null and examine_status=1) pending_shops,(select count(*) from ymcx_merchant_cash where is_delete=1 and deletetime is null and status=1) pending_merchant_cash,(select count(*) from ymcx_shop_cash where is_delete=1 and deletetime is null and status=1) pending_shop_cash,(select count(*) from ymcx_user where authentication=2) pending_auth,(select count(*) from ymcx_user where staff_authentication=2) pending_staff_auth,(select count(*) from ymcx_user) totaluser,(select count(*) from ymcx_admin) totaladmin,(select count(*) from ymcx_category) totalcategory,(select count(*) from information_schema.tables where table_schema=database()) dbtablenums,(select coalesce(sum(data_length+index_length),0) from information_schema.tables where table_schema=database()) dbsize,(select count(*) from ymcx_user where jointime>=#{today}) todayusersignup,(select count(*) from ymcx_user where logintime>=#{today}) todayuserlogin,(select count(*) from ymcx_user where jointime>=#{seven} or logintime>=#{seven} or prevtime>=#{seven}) sevendau,(select count(*) from ymcx_user where jointime>=#{thirty} or logintime>=#{thirty} or prevtime>=#{thirty}) thirtydau,(select count(*) from ymcx_user where jointime>=#{three}) threednu,(select count(*) from ymcx_user where jointime>=#{seven}) sevendnu,(select count(*) from ymcx_attachment) attachmentnums,(select coalesce(sum(filesize),0) from ymcx_attachment) attachmentsize,(select count(*) from ymcx_attachment where mimetype like 'image/%') picturenums,(select coalesce(sum(filesize),0) from ymcx_attachment where mimetype like 'image/%') picturesize")
  Map<String,Object> dashboard(@Param("today") long today,@Param("three") long three,@Param("seven") long seven,@Param("thirty") long thirty);
  @Select("select count(*) from ymcx_user where jointime>=#{start} and jointime<#{end}") int signupCount(@Param("start") long start,@Param("end") long end);

  @Select({"<script>select count(*) from <choose><when test='role == \"merchant\"'>ymcx_merchant</when><otherwise>ymcx_shop</otherwise></choose> where is_delete=1 and deletetime is null <if test='status != null'>and examine_status=#{status}</if></script>"}) int applicationCount(@Param("role") String role,@Param("status") Integer status);
  @Select({"<script>select * from <choose><when test='role == \"merchant\"'>ymcx_merchant</when><otherwise>ymcx_shop</otherwise></choose> where is_delete=1 and deletetime is null <if test='status != null'>and examine_status=#{status}</if> order by createtime desc limit #{limit} offset #{offset}</script>"}) List<Map<String,Object>> applications(@Param("role") String role,@Param("status") Integer status,@Param("limit") int limit,@Param("offset") int offset);

  @Select({"<script><choose><when test='kind == \"identity\"'>select id,nickname,avatar,authentication,authentication_mobile,authentication_name,authentication_card from ymcx_user where authentication=2</when><otherwise>select id,nickname,avatar,staff_authentication,staff_mobile,staff_name,staff_work from ymcx_user where staff_authentication=2</otherwise></choose> order by updatetime limit #{limit} offset #{offset}</script>"}) List<Map<String,Object>> authApplications(@Param("kind") String kind,@Param("limit") int limit,@Param("offset") int offset);
  @Select({"<script><choose><when test='kind == \"identity\"'>select count(*) from ymcx_user where authentication=2</when><otherwise>select count(*) from ymcx_user where staff_authentication=2</otherwise></choose></script>"}) int authApplicationCount(@Param("kind") String kind);

  @Select({"<script><choose><when test='role == \"merchant\"'>select count(*) from ymcx_merchant_cash c left join ymcx_merchant o on o.id=c.merchant_id and o.deletetime is null</when><otherwise>select count(*) from ymcx_shop_cash c left join ymcx_shop o on o.id=c.shop_id and o.deletetime is null</otherwise></choose> where c.is_delete=1 and c.deletetime is null <if test='status != null'>and c.status=#{status}</if><if test='keyword != null and keyword != \"\"'>and (c.out_trade_no like concat('%',#{keyword},'%') or o.name like concat('%',#{keyword},'%') or o.nickname like concat('%',#{keyword},'%') or o.mobile like concat('%',#{keyword},'%'))</if></script>"}) int cashCount(@Param("role") String role,@Param("status") Integer status,@Param("keyword") String keyword);
  @Select({"<script><choose><when test='role == \"merchant\"'>select coalesce(sum(c.amount),0) from ymcx_merchant_cash c left join ymcx_merchant o on o.id=c.merchant_id and o.deletetime is null</when><otherwise>select coalesce(sum(c.amount),0) from ymcx_shop_cash c left join ymcx_shop o on o.id=c.shop_id and o.deletetime is null</otherwise></choose> where c.is_delete=1 and c.deletetime is null and c.status=2 <if test='status != null'>and c.status=#{status}</if><if test='keyword != null and keyword != \"\"'>and (c.out_trade_no like concat('%',#{keyword},'%') or o.name like concat('%',#{keyword},'%') or o.nickname like concat('%',#{keyword},'%') or o.mobile like concat('%',#{keyword},'%'))</if></script>"}) BigDecimal paidCash(@Param("role") String role,@Param("status") Integer status,@Param("keyword") String keyword);
  @Select({"<script><choose><when test='role == \"merchant\"'>select c.*,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile from ymcx_merchant_cash c left join ymcx_merchant o on o.id=c.merchant_id and o.deletetime is null</when><otherwise>select c.*,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile from ymcx_shop_cash c left join ymcx_shop o on o.id=c.shop_id and o.deletetime is null</otherwise></choose> where c.is_delete=1 and c.deletetime is null <if test='status != null'>and c.status=#{status}</if><if test='keyword != null and keyword != \"\"'>and (c.out_trade_no like concat('%',#{keyword},'%') or o.name like concat('%',#{keyword},'%') or o.nickname like concat('%',#{keyword},'%') or o.mobile like concat('%',#{keyword},'%'))</if> order by c.createtime desc limit #{limit} offset #{offset}</script>"}) List<Map<String,Object>> cashRows(@Param("role") String role,@Param("status") Integer status,@Param("keyword") String keyword,@Param("limit") int limit,@Param("offset") int offset);
  @Select({"<script><choose><when test='role == \"merchant\"'>select c.id,c.out_trade_no,c.merchant_id,c.amount,c.status,c.note,c.createtime,c.updatetime,c.pay_time,c.pay_number,c.pay_money,c.examine_time,c.examine_id,c.examine_note,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile,u.nickname user_nickname,u.openid from ymcx_merchant_cash c left join ymcx_merchant o on o.id=c.merchant_id and o.deletetime is null left join ymcx_user u on u.id=o.user_id</when><otherwise>select c.id,c.out_trade_no,c.shop_id,c.amount,c.status,c.note,c.createtime,c.updatetime,c.pay_time,c.pay_number,c.pay_money,c.examine_time,c.examine_id,c.examine_note,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile,u.nickname user_nickname,u.openid from ymcx_shop_cash c left join ymcx_shop o on o.id=c.shop_id and o.deletetime is null left join ymcx_user u on u.id=o.user_id</otherwise></choose> where c.id=#{id} and c.is_delete=1 and c.deletetime is null</script>"}) Map<String,Object> cashDetail(@Param("role") String role,@Param("id") long id);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set is_delete=2,deletetime=#{now},updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null</script>"}) int deleteCash(@Param("role") String role,@Param("id") long id,@Param("now") long now);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set is_delete=2,deletetime=#{now},updatetime=#{now} where is_delete=1 and deletetime is null and id in <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></script>"}) int deleteCashRows(@Param("role") String role,@Param("ids") List<Long> ids,@Param("now") long now);
  @Select({"<script>select count(*) from <choose><when test='role == \"merchant\"'>ymcx_merchant_cash</when><otherwise>ymcx_shop_cash</otherwise></choose> where deletetime is not null</script>"}) int recycledCashCount(@Param("role") String role);
  @Select({"<script><choose><when test='role == \"merchant\"'>select c.*,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile from ymcx_merchant_cash c left join ymcx_merchant o on o.id=c.merchant_id</when><otherwise>select c.*,o.name owner_name,o.nickname owner_nickname,o.mobile owner_mobile from ymcx_shop_cash c left join ymcx_shop o on o.id=c.shop_id</otherwise></choose> where c.deletetime is not null order by c.deletetime desc,c.id desc limit #{limit} offset #{offset}</script>"}) List<Map<String,Object>> recycledCashRows(@Param("role") String role,@Param("limit") int limit,@Param("offset") int offset);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set is_delete=1,deletetime=null,updatetime=#{now} where deletetime is not null and id=#{id}</script>"}) int restoreCash(@Param("role") String role,@Param("id") long id,@Param("now") long now);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set is_delete=1,deletetime=null,updatetime=#{now} where deletetime is not null <if test='ids != null and !ids.isEmpty()'>and id in <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></if></script>"}) int restoreCashRows(@Param("role") String role,@Param("ids") List<Long> ids,@Param("now") long now);
  @Delete({"<script>delete from <choose><when test='role == \"merchant\"'>ymcx_merchant_cash</when><otherwise>ymcx_shop_cash</otherwise></choose> where deletetime is not null and id=#{id}</script>"}) int destroyCash(@Param("role") String role,@Param("id") long id);
  @Delete({"<script>delete from <choose><when test='role == \"merchant\"'>ymcx_merchant_cash</when><otherwise>ymcx_shop_cash</otherwise></choose> where deletetime is not null <if test='ids != null and !ids.isEmpty()'>and id in <foreach collection='ids' item='id' open='(' separator=',' close=')'>#{id}</foreach></if></script>"}) int destroyCashRows(@Param("role") String role,@Param("ids") List<Long> ids);
  @Select({"<script>select count(*) from <choose><when test='role == \"merchant\"'>ymcx_merchant</when><otherwise>ymcx_shop</otherwise></choose> where id=#{id} and is_delete=1 and deletetime is null</script>"}) int cashOwnerExists(@Param("role") String role,@Param("id") long id);
  @Insert({"<script><choose><when test='role == \"merchant\"'>insert into ymcx_merchant_cash(out_trade_no,merchant_id,amount,status,note,createtime,updatetime,is_delete,pay_time,pay_number,pay_money)</when><otherwise>insert into ymcx_shop_cash(out_trade_no,shop_id,amount,status,note,createtime,updatetime,is_delete,pay_time,pay_number,pay_money)</otherwise></choose> values(#{number},#{ownerId},#{amount},#{status},#{note},#{now},#{now},1,#{payTime},#{payNumber},#{payMoney})</script>"}) int insertCash(@Param("role") String role,@Param("number") String number,@Param("ownerId") long ownerId,@Param("amount") BigDecimal amount,@Param("status") int status,@Param("note") String note,@Param("now") long now,@Param("payTime") long payTime,@Param("payNumber") String payNumber,@Param("payMoney") BigDecimal payMoney);

  @Select({"<script><choose><when test='role == \"merchant\"'>select id,user_id,examine_status from ymcx_merchant</when><otherwise>select id,user_id,examine_status from ymcx_shop</otherwise></choose> where id=#{id} and is_delete=1 and deletetime is null for update</script>"}) Map<String,Object> lockApplication(@Param("role") String role,@Param("id") long id);
  @Select({"<script>select count(*) from <choose><when test='role == \"merchant\"'>ymcx_merchant</when><otherwise>ymcx_shop</otherwise></choose> where username=#{username} and id&lt;&gt;#{id} and is_delete=1 and deletetime is null</script>"}) int applicationUsernameCount(@Param("role") String role,@Param("username") String username,@Param("id") long id);
  @Update("update ymcx_merchant set username=#{username},salt=#{salt},password=#{password},commission_normal_rate=#{v.commission_normal_rate},commission_merchant_rate=#{v.commission_merchant_rate},commission_shop_rate=#{v.commission_shop_rate},service_distance1=#{v.service_distance1},service_distance2=#{v.service_distance2},service_distance3=#{v.service_distance3},service_distance4=#{v.service_distance4},service_money1=#{v.service_money1},service_money2=#{v.service_money2},service_money3=#{v.service_money3},service_money4=#{v.service_money4},service_money5=#{v.service_money5},examine_status=2,examine_time=#{now},examine_id=#{admin},examine_note='',updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null")
  int approveMerchant(@Param("id") long id,@Param("username") String username,@Param("salt") String salt,@Param("password") String password,@Param("v") Map<String,Integer> settings,@Param("admin") long admin,@Param("now") long now);
  @Update("update ymcx_shop set username=#{username},salt=#{salt},password=#{password},commission_shop_rate=#{v.commission_shop_rate},examine_status=2,examine_time=#{now},examine_id=#{admin},examine_note='',updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null")
  int approveShop(@Param("id") long id,@Param("username") String username,@Param("salt") String salt,@Param("password") String password,@Param("v") Map<String,Integer> settings,@Param("admin") long admin,@Param("now") long now);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant</when><otherwise>update ymcx_shop</otherwise></choose> set examine_status=3,examine_time=#{now},examine_id=#{admin},examine_note=#{note},updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null</script>"}) int rejectApplication(@Param("role") String role,@Param("id") long id,@Param("note") String note,@Param("admin") long admin,@Param("now") long now);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_user set merchant_status=#{status},updatetime=#{now}</when><otherwise>update ymcx_user set shop_status=#{status},updatetime=#{now}</otherwise></choose> where id=#{userId}</script>"}) int updateApplicationUser(@Param("role") String role,@Param("userId") long userId,@Param("status") int status,@Param("now") long now);
  @Update({"<script><choose><when test='kind == \"identity\"'>update ymcx_user set authentication=#{status},updatetime=#{now} where id=#{id} and authentication=2</when><otherwise>update ymcx_user set staff_authentication=#{status},updatetime=#{now} where id=#{id} and staff_authentication=2</otherwise></choose></script>"}) int examineAuth(@Param("kind") String kind,@Param("id") long id,@Param("status") int status,@Param("now") long now);

  @Select({"<script><choose><when test='role == \"merchant\"'>select * from ymcx_merchant_cash</when><otherwise>select * from ymcx_shop_cash</otherwise></choose> where id=#{id} and status=1 and is_delete=1 and deletetime is null for update</script>"}) Map<String,Object> lockCash(@Param("role") String role,@Param("id") long id);
  @Select({"<script><choose><when test='role == \"merchant\"'>select money from ymcx_merchant</when><otherwise>select money from ymcx_shop</otherwise></choose> where id=#{id} and is_delete=1 and deletetime is null for update</script>"}) Map<String,Object> lockOwnerMoney(@Param("role") String role,@Param("id") long id);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set status=3,note=#{note},examine_note=#{note},examine_time=#{now},examine_id=#{admin},updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null</script>"}) int rejectCash(@Param("role") String role,@Param("id") long id,@Param("note") String note,@Param("admin") long admin,@Param("now") long now);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant</when><otherwise>update ymcx_shop</otherwise></choose> set money=#{money},updatetime=#{now} where id=#{id} and is_delete=1 and deletetime is null</script>"}) int updateOwnerMoney(@Param("role") String role,@Param("id") long id,@Param("money") BigDecimal money,@Param("now") long now);
  @Insert({"<script><choose><when test='role == \"merchant\"'>insert into ymcx_merchant_money_log(merchant_id,money,`before`,`after`,type,memo,createtime,updatetime,is_delete,order_id)</when><otherwise>insert into ymcx_shop_money_log(shop_id,money,`before`,`after`,type,memo,createtime,updatetime,is_delete,order_id)</otherwise></choose> values(#{ownerId},#{amount},#{before},#{after},3,#{memo},#{now},#{now},1,#{cashId})</script>"}) int insertRefundLog(@Param("role") String role,@Param("ownerId") long ownerId,@Param("amount") BigDecimal amount,@Param("before") BigDecimal before,@Param("after") BigDecimal after,@Param("memo") String memo,@Param("now") long now,@Param("cashId") long cashId);
  @Select({"<script><choose><when test='role == \"merchant\"'>select c.*,u.openid from ymcx_merchant_cash c join ymcx_merchant o on o.id=c.merchant_id and o.is_delete=1 and o.deletetime is null join ymcx_user u on u.id=o.user_id</when><otherwise>select c.*,u.openid from ymcx_shop_cash c join ymcx_shop o on o.id=c.shop_id and o.is_delete=1 and o.deletetime is null join ymcx_user u on u.id=o.user_id</otherwise></choose> where c.id=#{id} and c.status=1 and c.is_delete=1 and c.deletetime is null for update</script>"}) Map<String,Object> lockCashForTransfer(@Param("role") String role,@Param("id") long id);
  @Update({"<script><choose><when test='role == \"merchant\"'>update ymcx_merchant_cash</when><otherwise>update ymcx_shop_cash</otherwise></choose> set status=2,pay_number=#{batchId},pay_time=#{now},pay_money=#{amount},examine_time=#{now},examine_id=#{admin},examine_note=#{note},updatetime=#{now} where id=#{id} and status=1 and is_delete=1 and deletetime is null</script>"}) int approveCash(@Param("role") String role,@Param("id") long id,@Param("batchId") String batchId,@Param("amount") BigDecimal amount,@Param("admin") long admin,@Param("note") String note,@Param("now") long now);
  @Insert("insert into ymcx_platform_log(user_id,amount,type,log_note,order_id,createtime,is_delete,user_type) values(#{ownerId},#{amount},#{type},#{note},#{cashId},#{now},1,#{userType})") int insertPlatformWithdrawal(@Param("ownerId") long ownerId,@Param("amount") BigDecimal amount,@Param("type") int type,@Param("note") String note,@Param("cashId") long cashId,@Param("now") long now,@Param("userType") int userType);
}
